        let sheer = |u: f32| by - d - 3.5 * bt * u * u - 1.5 * bt * (u < 0.0) as i32 as f32 * u * u;
        let rows = 6;
        for k in 0..rows {
            let v = k as f32 / (rows - 1) as f32;
            let (u0, u1) = (-1.0 + 0.45 * v, 1.0 - 0.12 * v);
