            }).collect();
            hull.reload(pile(&st, if v < 0.3 { "#4a3f35" } else { "#2c2622" }, 0.93, 0.7), 0.7);
            c.drag(&mut hull, &Gesture::new(pts).pressure(0.8, 0.75).ramps(0.05, 0.1).shake(0.5), None);
        }
